package com.sza.streamsplayer.data.exchange.publish

import java.security.SecureRandom
import java.util.Base64

/**
 * Mints a `broadcastId` in the share id form (DEVICE-EXCHANGE 6.3 via ANYWHERE-ACCESS 6.2): 16 bytes
 * from a cryptographically secure generator, base64url without padding, 22 characters, generated by
 * the producer and never by the server. A new id per broadcast is the capability of the secret-link
 * model, so it never reaches a log (7.9).
 */
object BroadcastIdGenerator {

    private const val ID_BYTES = 16

    fun generate(random: SecureRandom = SecureRandom()): String =
        Base64.getUrlEncoder().withoutPadding().encodeToString(ByteArray(ID_BYTES).also(random::nextBytes))
}
